import type { Metadata } from "next"; import Link from "next/link"; import { redirect } from "next/navigation";
import { hasAdminSession } from "../_lib/session"; import DispatchAdminNav from "../_components/DispatchAdminNav"; import { Active, input, label, priorityOptions, Select, textarea, Zones } from "../_components/DispatchFormFields";
import { getDispatchVendor, listDispatchVendors } from "@/lib/dispatch/vendors"; import { listDispatchVehicles } from "@/lib/dispatch/vehicles"; import { listDispatchDrivers } from "@/lib/dispatch/drivers"; import { NORMAL_RENTAL_ZONES } from "@/lib/normal-rental/zones"; import { saveVendor } from "./actions";
import { DISPATCH_CREATION_DEFAULTS } from "@/lib/dispatch/admin-presentation";
export const metadata:Metadata={title:"Dispatch Vendors | RentKA Admin",robots:{index:false,follow:false,noarchive:true,nosnippet:true}};
const badge=(active:boolean)=>active?"bg-green-100 text-green-800":"bg-slate-200 text-slate-700";
export default async function Page({searchParams}:{searchParams:Promise<Record<string,string|undefined>>}){if(!(await hasAdminSession()))redirect("/admin/pricing-calculator");const q=await searchParams;const [all,vehicles,drivers,editing]=await Promise.all([listDispatchVendors(),listDispatchVehicles(),listDispatchDrivers(),q.edit?getDispatchVendor(q.edit):null]);const rows=all.filter(v=>(!q.search||`${v.name} ${v.contactName??""} ${v.primaryPhone}`.toLowerCase().includes(q.search.toLowerCase()))&&(!q.zone||v.zoneIds.includes(q.zone as never))&&(!q.state||(q.state==="active"?v.active:!v.active)));return <main className="min-h-screen bg-slate-100 p-4 md:p-8"><div className="mx-auto max-w-7xl"><DispatchAdminNav current="vendors"/><header className="mb-6"><p className="text-sm font-bold uppercase tracking-widest text-[#5BAE4A]">Dispatch operations</p><h1 className="text-3xl font-black text-[#0F2B46]">Vendors</h1><p className="text-slate-600">Private operational partners. These records do not change public vendors or inventory.</p></header>{q.error&&<p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{q.error}</p>}{q.saved&&<p className="mb-4 rounded-lg bg-green-50 p-3 text-sm text-green-800">{q.saved}</p>}
<section className="mb-6 rounded-2xl bg-white p-5 shadow-sm"><h2 className="text-xl font-black text-[#0F2B46]">{editing?"Edit vendor":"Add vendor"}</h2><form action={saveVendor} className="mt-4 grid gap-4 md:grid-cols-2"><input type="hidden" name="id" value={editing?.id??""}/><label className={label}>Vendor/company name<input className={input} name="name" required maxLength={160} defaultValue={editing?.name}/></label><label className={label}>Primary contact name<input className={input} name="contactName" maxLength={120} defaultValue={editing?.contactName}/></label><label className={label}>Primary phone<input className={input} name="primaryPhone" required maxLength={40} placeholder="03020589999" defaultValue={editing?.primaryPhone}/></label><label className={label}>WhatsApp number<input className={input} name="whatsappNumber" required maxLength={40} placeholder="923020589999" defaultValue={editing?.whatsappNumber}/></label><Zones selected={editing?.zoneIds}/><label className={label}>Priority<Select name="priority" value={editing?.priority??DISPATCH_CREATION_DEFAULTS.vendor.priority} options={priorityOptions}/></label><details className="md:col-span-2 rounded-xl border p-4"><summary className="cursor-pointer font-black text-[#0F2B46]">Optional existing-record references</summary><div className="mt-4 grid gap-4 md:grid-cols-2"><label className={label}>Legacy public vendor ID<input className={input} name="legacyVendorId" defaultValue={editing?.legacyVendorId}/></label><label className={label}>Normal rental vendor ID<input className={input} name="normalRentalVendorId" defaultValue={editing?.normalRentalVendorId}/></label></div></details><label className={`${label} md:col-span-2`}>Internal notes<textarea className={textarea} name="notes" defaultValue={editing?.notes}/></label><Active value={editing?.active??DISPATCH_CREATION_DEFAULTS.vendor.active}/><div className="flex gap-2"><button className="rounded-lg bg-[#0F2B46] px-5 py-2.5 font-bold text-white">Save vendor</button>{editing&&<Link href="/admin/vendors" className="rounded-lg border px-5 py-2.5">Cancel</Link>}</div></form></section>
<form className="mb-4 grid gap-2 rounded-xl bg-white p-3 sm:grid-cols-4"><input className={input} name="search" placeholder="Search name or phone" defaultValue={q.search}/><select className={input} name="zone" defaultValue={q.zone??""}><option value="">All zones</option>{Object.entries(NORMAL_RENTAL_ZONES).map(([id,z])=><option key={id} value={id}>{z.label}</option>)}</select><select className={input} name="state" defaultValue={q.state??""}><option value="">All states</option><option value="active">Active</option><option value="inactive">Inactive</option></select><button className="rounded-lg bg-slate-800 px-4 py-2 text-white">Filter</button></form>
<section className="grid gap-4">{rows.map(v=>{const vc=vehicles.filter(x=>x.vendorId===v.id).length,dc=drivers.filter(x=>x.vendorId===v.id).length;return <article key={v.id} className="rounded-2xl bg-white p-5 shadow-sm"><div className="flex flex-wrap justify-between gap-3"><div><div className="flex items-center gap-2"><h2 className="text-lg font-black text-[#0F2B46]">{v.name}</h2><span className={`rounded-full px-2 py-1 text-xs font-bold ${badge(v.active)}`}>{v.active?"Active":"Inactive"}</span><span className="rounded-full bg-blue-50 px-2 py-1 text-xs">{v.priority}</span></div><p className="mt-1 text-sm">{v.contactName||"No contact name"} · {v.primaryPhone} · WhatsApp {v.whatsappNumber}</p><p className="mt-1 text-xs text-slate-500">{v.zoneIds.map(z=>NORMAL_RENTAL_ZONES[z].label).join(" · ")}</p></div><Link href={`/admin/vendors?edit=${v.id}`} className="h-fit rounded-lg border px-4 py-2 text-sm font-bold">Edit / {v.active?"deactivate":"reactivate"}</Link></div><div className="mt-4 flex gap-3 text-sm"><Link className="font-bold text-[#0F2B46] underline" href={`/admin/vehicles?vendor=${v.id}`}>{vc} vehicle{vc===1?"":"s"}</Link><Link className="font-bold text-[#0F2B46] underline" href={`/admin/drivers?vendor=${v.id}`}>{dc} driver{dc===1?"":"s"}</Link></div></article>})}{!rows.length&&<p className="rounded-xl border border-dashed bg-white p-6 text-center text-slate-500">No vendors match these filters.</p>}</section></div></main>}
